def consistent(off,n): return bytes(((off+i)*7+3)&0xff for i in range(n))
def widths(value): return [w for w in (1,2,4,8) if value < 2**(8*w-2)]
def vw(value): return vmin(value, random.choice(widths(value)))

def run_logged(traces):
    if LOG.exists(): LOG.unlink()
    data = json.dumps({'traces': traces}).encode()
    p = subprocess.run(['python3','/workspace/run.py','/workspace/tmp/classes'], input=data, capture_output=True)
    assert p.returncode==0, p.stderr.decode()[:2000]
    lines = LOG.read_text().split() if LOG.exists() else []
    return json.loads(p.stdout), [bytes.fromhex(x) for x in lines]

def gen_trace(seed, nevents=80):
    random.seed(seed)
    events=[{'keys':['I','H','A']}]
    ann=[]
    pn={'I':0,'H':0,'A':0}
    ncids={}
    for e in range(nevents):
        lvl=random.choice(['I','H','A'])
        bodies=[]
        for f in range(random.randint(1,6)):
            k=random.randrange(10)
            rid=random.choice([0,4,8,12])          # client bidi
            uid=random.choice([2,6,10])            # client uni
            sid=random.choice([1,5])               # server bidi (open: local_bidi=2)
            suid=random.choice([3,7])              # server uni
            if k==0:
                off=random.randrange(0,60)*4; n=random.randrange(0,40)
                bodies.append(stream(random.choice([rid,uid,sid]), off, consistent(off,n), fin=False,
                                     offset=random.random()<0.8, length=random.random()<0.8))
            elif k==1:
                off=random.randrange(0,60)*4; n=random.randrange(0,40); bodies.append(crypto(off, consistent(off,n)))
            elif k==2:
                lg=random.randrange(0,300)
                b=bytes([random.choice([2,3])])+vw(lg)+vw(random.randrange(5))+vw(0)+vw(random.randrange(0,lg+1))
                if b[0]==3: b+=vw(1)+vw(2)+vw(3)
                bodies.append(b)
            elif k==3: bodies.append(b'\x00'*random.randrange(1,5)+b'\x01')
            elif k==4: bodies.append(b'\x10'+vw(random.randrange(0,10**6)))
            elif k==5: bodies.append(b'\x15'+vw(random.choice([rid,uid,sid]))+vw(0))
            elif k==6: bodies.append(b'\x11'+vw(random.choice([rid,sid,suid]))+vw(random.randrange(10**4)))
            elif k==7:
                sq=random.randrange(1,4); ncids[sq]=bytes([0xd0+sq])
                bodies.append(b'\x18'+vw(sq)+vw(0)+b'\x01'+ncids[sq]+b'\x22'*16)
            elif k==8: bodies.append(random.choice([b'\x14'+vw(3), b'\x16'+vw(2), b'\x17'+vw(1),
                                                    b'\x1a'+b'12345678', b'\x1b'+b'87654321',
                                                    b'\x31'+vw(2)+b'xy', b'\x05'+vw(random.choice([rid,sid,suid]))+vw(3),
                                                    b'\x04'+vw(random.choice([rid,uid,sid]))+vw(7)+vw(10**9),
                                                    b'\x19'+vw(1)]))
            else: bodies.append(b'\x06'+vw(random.randrange(0,200)*4)+vw(0))
        if lvl!='A':
            bodies=[b for b in bodies if b[:1] in (b'\x00',b'\x01',b'\x02',b'\x03',b'\x06')] or [b'\x01']
        body=b''.join(bodies)
        w=envelope(lvl, pn[lvl], body, width=random.choice([1,2,4]), cid=random.choice([b'\xaa',b'\xbb']), phase=0)
        pn[lvl]+=1
        events.append(datagram(w, auth=(0,)))
        ann.append((lvl,0,w))
    return trace(events, local_bidi=2, local_uni=2), ann

